//! ↩️ create-accessor leaf-owned inverse reconstruction from exact base values.
use serde::{Deserialize, Serialize};
use crate::artifacts::gltf::GltfSnapshot;
use crate::artifacts::gltf::schema::snapshot::GltfAccessor;
use crate::artifacts::gltf::schema::mutations::create_accessor::mutation::{validate, GltfCreateAccessorPayload};
use crate::artifacts::gltf::schema::mutations::top_level_collections_private::{accessors_op, reject, repair, Change, GltfTopLevelFamily, GltfTopLevelMutationRejection};
pub const ID: &str = "s.stdio.gltf.mutation.create-accessor.v1.inverse";
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(tag = "kind", rename_all = "camelCase")]
pub enum GltfCreateAccessorInverseOperation { Insert { position: usize, item: GltfAccessor }, Delete { index: usize, removed: GltfAccessor }, Move { index: usize, position: usize }, Reorder { order: Vec<usize> } }
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(rename_all = "camelCase")]
pub struct GltfCreateAccessorInverse { pub id: String, pub version: u32, pub touched_paths: Vec<String>, pub payload: GltfCreateAccessorPayload, pub operation: GltfCreateAccessorInverseOperation }
fn operation(payload: &GltfCreateAccessorPayload, base: &GltfSnapshot) -> GltfCreateAccessorInverseOperation { GltfCreateAccessorInverseOperation::Delete { index: payload.position, removed: GltfAccessor { buffer_view: None, byte_offset: 0, component_type: payload.component_type, normalized: false, count: payload.count, kind: payload.kind, max: None, min: None, sparse: None, name: None, extensions: None, extras: None } } }
fn touched_paths(payload: &GltfCreateAccessorPayload) -> Vec<String> { vec![format!("document/accessors/{}", payload.position)] }
pub fn validate_inverse(inverse: &GltfCreateAccessorInverse) -> Result<(), GltfTopLevelMutationRejection> { if inverse.id != ID || inverse.version != 1 { return Err(reject("gltf.mutation.invalid-inverse-envelope", "inverse", "descriptor identity does not match")); } if inverse.touched_paths != touched_paths(&inverse.payload) { return Err(reject("gltf.mutation.invalid-touched-paths", "inverse/touchedPaths", "paths must be concrete payload-derived locations")); } Ok(()) }
pub fn apply_inverse(inverse: &GltfCreateAccessorInverse, after: &GltfSnapshot) -> Result<GltfSnapshot, GltfTopLevelMutationRejection> { validate_inverse(inverse)?; let operation = &inverse.operation; match operation { GltfCreateAccessorInverseOperation::Insert { position, .. } if *position > after.document.accessors.len() => return Err(reject("gltf.mutation.insert-out-of-range", "document/accessors", "position must be within the collection")), GltfCreateAccessorInverseOperation::Delete { index, .. } if *index >= after.document.accessors.len() => return Err(reject("gltf.mutation.index-out-of-range", "document/accessors", "index must address an item")), GltfCreateAccessorInverseOperation::Move { index, position } if *index >= after.document.accessors.len() || *position >= after.document.accessors.len() => return Err(reject("gltf.mutation.index-out-of-range", "document/accessors", "indices must address items")), GltfCreateAccessorInverseOperation::Reorder { order } if order.is_empty() || order.len() != after.document.accessors.len() || order.iter().collect::<std::collections::BTreeSet<_>>().len() != order.len() || order.iter().any(|index| *index >= after.document.accessors.len()) => return Err(reject("gltf.mutation.invalid-permutation", "document/accessors", "order must be a non-empty permutation")), _ => {} } let mut next = after.clone(); match operation { GltfCreateAccessorInverseOperation::Insert { position, item } => { repair(&mut next.document, GltfTopLevelFamily::Accessors, &Change::Insert(*position))?; next.document.accessors.insert(*position, item.clone());  }, GltfCreateAccessorInverseOperation::Delete { index, .. } => { accessors_op(&mut next, GltfTopLevelFamily::Accessors, *index, None, None)?;  }, GltfCreateAccessorInverseOperation::Move { index, position } => { accessors_op(&mut next, GltfTopLevelFamily::Accessors, *index, Some(*position), None)?;  }, GltfCreateAccessorInverseOperation::Reorder { order } => { accessors_op(&mut next, GltfTopLevelFamily::Accessors, order[0], None, Some(order))?;  } } Ok(next) }
pub fn encode(inverse: &GltfCreateAccessorInverse) -> Result<Vec<u8>, GltfTopLevelMutationRejection> { serde_json::to_vec(inverse).map_err(|error| reject("gltf.mutation.encode-failed", "inverse", error.to_string())) }
pub fn derive(payload: &GltfCreateAccessorPayload, base: &GltfSnapshot) -> Result<GltfCreateAccessorInverse, GltfTopLevelMutationRejection> { validate(payload, base)?; Ok(GltfCreateAccessorInverse { id: ID.into(), version: 1, touched_paths: touched_paths(payload), payload: payload.clone(), operation: operation(payload, base) }) }
